/* Version 2 workspace. Dynamic values are escaped before HTML rendering. */
const v2Style=document.createElement('style');v2Style.textContent=`textarea{width:100%;min-height:90px;background:var(--bg);color:var(--text);border:1px solid var(--line);padding:12px;border-radius:8px;font:inherit} .v2grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.v2grid .card{min-width:0}.v2buttons{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.v2table{overflow:auto}.v2table td{vertical-align:top;overflow-wrap:anywhere}.v2secret{white-space:pre-wrap;overflow-wrap:anywhere}.v2hint{font-size:12px;color:var(--muted)}.v2stat{font-size:26px;color:var(--mint)}.v2form label:not(.check){display:block;margin-top:12px}.v2form input,.v2form select{width:100%}.v2form input[type=checkbox]{width:auto} @media(max-width:900px){.v2grid{grid-template-columns:1fr}}`;document.head.append(v2Style);
const nav2=[['assets','◌','AI asset visibility'],['mcpinspect','⬡','MCP tools'],['redteam','◈','Expanded red team'],['protection','▣','Runtime protection'],['violations','◍','Violations'],['deployment','⌕','Deployment checks'],['integrity','◇','Integrity & canaries']];
document.querySelector('nav [data-page="overview"]').insertAdjacentHTML('afterend',nav2.map(([id,icon,name])=>`<button data-page="${id}" data-v2page="${id}"><span class="navicon">${icon}</span>${name}</button>`).join(''));
const field=(id,label,placeholder='',type='text')=>`<label for="${id}">${label}</label><input id="${id}" type="${type}" placeholder="${placeholder}" autocomplete="off">`;
const select=(id,label,options)=>`<label for="${id}">${label}</label><select id="${id}">${options.map(([value,name])=>`<option value="${value}">${name}</option>`).join('')}</select>`;
const check=(id,label,checked=false)=>`<label class="check"><input type="checkbox" id="${id}" ${checked?'checked':''}><span>${label}</span></label>`;
const card=(title,content)=>`<div class="card v2form"><h2>${title}</h2>${content}</div>`;
const button=(id,text)=>`<button class="primary" id="${id}">${text}</button>`;
const page=(id,title,intro,body)=>`<section id="${id}" class="page hidden"><div class="eyebrow">RAY-I / SECURITY WORKSPACE</div><h1>${title}</h1><p class="intro">${intro}</p>${body}</section>`;
document.querySelector('main > footer').insertAdjacentHTML('beforebegin',
page('assets','AI asset visibility','Discover local agents and MCP configurations, register models, and inspect each asset’s controls and risk evidence.',
 `<div class="v2buttons">${button('v2Refresh','Refresh assets')}<button class="secondary" id="assetExport">Export registry</button></div><div id="assetSummary" class="notice">Loading local registry…</div><div id="assetList"></div><div class="v2grid">`+
 card('Discover local projects',`<label for="discoveryRoots">Absolute folders or configuration files, one per line</label><textarea id="discoveryRoots" placeholder="D:\\AI\\my-project&#10;C:\\path\\mcp.json"></textarea><p class="v2hint">Recognizes AGENTS.md, SKILL.md, CLAUDE.md, MCP JSON and Codex TOML. No processes launched or credentials collected.</p>${button('discoverAssets','Discover assets')}<p id="discoveryResult"></p>`)+
 card('Register an asset',field('assetName','Name')+select('assetKind','Type',[['model','Model'],['agent','Agent'],['mcp','MCP server'],['repository','Repository']])+field('assetTarget','Absolute path or endpoint')+field('assetModel','Model identity, for model assets')+field('assetOwner','Owner')+button('saveAsset','Register asset'))+
 card('Discover running models',select('assetProvider','Provider',[['ollama','Ollama'],['openai','OpenAI-compatible']])+field('assetEndpoint','Endpoint','http://127.0.0.1:11434')+field('assetKey','Bearer key, optional and kept in memory','','password')+check('assetAuthorized','I am authorized to query this endpoint')+button('discoverModels2','Discover and register models'))+
 card('Assign controls and evidence',select('assignAsset','Asset',[])+select('assignPolicy','Policy',[])+field('assignOwner','Owner')+`<div class="v2buttons">${button('assignControls','Assign policy')}<button class="secondary" id="attachEvidence">Link current report</button></div><p class="v2hint">Reports must exactly match the asset target and model. An assigned policy is enforced only through a running gateway route.</p>`)+`</div>`)+
page('mcpinspect','MCP server and tool scanning','Inspect live HTTP tool descriptors, schemas, capability hints, and changes without invoking a tool.',
 card('Inspect selected server',select('mcpAsset','Registered MCP asset',[])+field('mcpUrl','MCP HTTP endpoint','http://127.0.0.1:9000/mcp')+field('mcpKey','Bearer key, optional','','password')+check('mcpAuthorized','I am authorized to inspect this endpoint')+button('mcpRun','Scan MCP server')+`<p class="v2hint">Select a matching registered asset to save descriptor hashes for runtime change detection. Stdio entries are discovered as configuration only. HTTP scan supports JSON and bounded SSE responses.</p>`))+
page('redteam','Expanded algorithmic red team','240 generated cases across 24 attack families and 10 delivery forms, with adaptive prioritization after observed failures.',
 card('Choose a model and budget',select('rtProvider','Provider',[['ollama','Ollama'],['openai','OpenAI-compatible']])+field('rtUrl','Endpoint','http://127.0.0.1:11434')+field('rtKey','Bearer key, optional','','password')+check('rtAuthorized','I am authorized to test this endpoint; inference may incur cost')+button('rtDiscover','Discover models')+select('rtModel','Model',[])+select('rtCases','Case budget',[['24','24 cases'],['80','80 cases'],['240','All 240 cases']])+field('rtMinutes','Time budget in minutes, 1–30','10','number')+field('rtSeed','Reproducible order seed','0','number')+check('rtAdaptive','Prioritize variants of families with observed failures',true)+button('rtRun','Run red team')+`<p class="v2hint">Synthetic confidentiality, instruction hierarchy and tool-claim tests. Case count is not the count of independently validated techniques. Failed calls remain inconclusive.</p>`))+
page('protection','Runtime protection','Protect routed model and MCP traffic with per-asset rules, allowlists, request budgets, and input/output inspection.',
 `<div id="gatewayStatus" class="notice"></div><div class="v2buttons">${button('gatewayStart','Start local gateway')}<button class="secondary" id="gatewayStop">Stop gateway</button></div><div class="v2grid">`+
 card('Model and agent policy',select('editPolicy','Edit policy',[])+field('policyName','Policy name')+select('policyMode','Text-rule mode',[['block','Block matches'],['monitor','Observe text matches']])+check('policySecurity','Security patterns',true)+check('policyPrivacy','Personal data and credential patterns',true)+check('policySafety','Safety patterns',true)+field('policyInput','Maximum input characters','24000','number')+field('policyOutput','Maximum output characters','32000','number')+field('policyTokens','Maximum output tokens','1024','number')+field('policyRate','Requests per minute, shared by route','30','number')+field('policyBudget','Maximum requests per route per gateway session','100','number')+`<label for="policyTools">Allowed tool/action names, one per line</label><textarea id="policyTools"></textarea><label for="policyDomains">Allowed destination hostnames, one per line</label><textarea id="policyDomains" placeholder="Empty means no domain filter"></textarea><label for="policyPhrases">Blocked phrases, one per line</label><textarea id="policyPhrases"></textarea><label for="policySystem">Model system instruction</label><textarea id="policySystem"></textarea><div class="v2buttons">${button('policySave','Save policy')}<button class="secondary" id="policyNew">New policy</button></div><p class="v2hint">Size limits and tool/domain allowlists remain blocking in observe mode. Text detectors are heuristic. An empty tool allowlist denies all tools.</p>`)+
 card('Connect an asset to enforcement',select('routeAsset','Asset',[])+select('routeProvider','Model upstream type',[['ollama','Ollama'],['openai','OpenAI-compatible']])+field('routeUpstream','Upstream URL; defaults to asset target')+field('routeKeyEnv','Upstream credential environment variable name, optional')+check('routeAuthorized','I authorize calls to this upstream through this gateway')+button('routeSave','Create or rotate route token')+`<pre id="routeSecret" class="v2secret"></pre><p class="v2hint">Client token is shown once. Model clients use the returned /v1 base URL with stream=false. MCP clients use the exact returned URL. Direct traffic bypasses this gateway. MCP allowlisted tools must first be scanned; changed descriptors are blocked. Agent /check is a preflight decision the caller must honor.</p><div id="routeList"></div>`)+
 card('Try policy rules',select('previewPolicy','Policy',[])+select('previewPoint','Enforcement point',[['model-input','Model input'],['model-output','Model output'],['mcp-input','MCP arguments'],['mcp-output','MCP results']])+field('previewTool','Tool name, optional')+`<label for="previewText">Synthetic sample</label><textarea id="previewText" placeholder="Use fake data for a policy check"></textarea>${button('previewRun','Evaluate sample')}<pre id="previewResult"></pre>`)+
 card('Enforcement coverage',`<p>Active controls apply at model input/output and MCP argument/result boundaries. Rate and action budgets are shared by route. Tool names, pinned descriptors, and supported argument schemas are checked before execution.</p><p>MCP result checks occur after upstream execution and cannot undo side effects. Streaming, multimodal requests, model tool calls, and unsupported schemas fail closed. Content checks can miss obfuscation and semantic harm.</p><p>Gateway starts on demand and stops with the app. Enabled integrity schedules resume when the app starts. Neither feature installs a system service.</p>`)+`</div>`)+
page('violations','Violations and alerts','Inspect redacted gateway decisions, canary observations, and integrity alerts without storing request or response bodies.',
 `<div class="v2buttons">${button('violationsRefresh','Refresh decisions')}<button class="secondary" id="violationsExport">Export decisions</button></div><div id="violationCounts" class="notice"></div>${select('violationFilter','Decision',[['all','All'],['block','Blocked'],['monitor','Observed matches'],['alert','Alerts'],['error','Errors'],['allow','Allowed']])}<div id="violationList" class="v2table"></div>`)+
page('deployment','Deployment checks','Assess inference exposure, AI web UIs, GPU isolation, RAG sources, stored secrets, egress, and resource settings.',
 `<div class="v2grid">`+card('Run a scoped assessment',select('deployMode','Assessment',[['inference','1. Inference API exposure'],['configuration','3 / 10. AI web UI and resource configuration'],['gpu','4. GPU stack'],['rag','5. RAG and vector database'],['at_rest','8. Secrets and personal data at rest'],['egress','9. Container egress lockdown'],['signature','7. Model signature verification']])+`<div data-dm="inference,rag,egress">${field('deployUrl','Target endpoint or controlled egress destination','http://127.0.0.1:11434')}</div><div data-dm="inference">${select('deployService','Inference service',[['ollama','Ollama'],['vllm','vLLM'],['lmstudio','LM Studio'],['comfyui','ComfyUI'],['gradio','Gradio']])}</div><div data-dm="rag">${select('vectorService','Vector service',[['qdrant','Qdrant'],['chroma','Chroma'],['weaviate','Weaviate'],['milvus','Milvus']])}</div><div data-dm="configuration,rag,at_rest,signature">${field('deployPath','Absolute file or folder path')}</div><div data-dm="configuration">${field('deployDb','Open WebUI SQLite database, optional')}${check('deployResources','Include resource limit and proxy configuration checks',true)}</div><div data-dm="at_rest">${check('useGitleaks','Include installed Gitleaks engine',true)}</div><div data-dm="gpu">${check('gpuTenants','Several tenants share this GPU')}</div><div data-dm="egress">${field('egressContainer','Exact running container name or ID')}${field('egressDns','DNS test name','example.com')}<p class="v2hint">Runs a fixed python3 probe inside the chosen container. Tests the selected destination, DNS resolution and a TCP connection to metadata port 80. No metadata HTTP request or credentials are read. Python3 must already be installed.</p></div><div data-dm="signature">${field('signaturePath','Signature file')}${field('signerIdentity','Expected signing identity')}${field('signerIssuer','Expected OIDC issuer','https://token.actions.githubusercontent.com')}${check('signatureOnline','Allow public Sigstore trust-service access')}</div><div data-dm="inference,rag,egress">${check('deployAuthorized','I authorize the selected endpoint or container probes')}</div>${button('deployRun','Run assessment')}<p id="deployHint" class="v2hint"></p>`)+
 card('2. Outside-in VPS probe',`<p>Copy <b>remote_probe.py</b> from the app folder to a second machine outside the VPS network. Probe only the host and ports you own or are authorized to assess.</p><pre>python remote_probe.py --target YOUR_VPS_HOST --ports 11434,8000,7860,8188 --authorized --output outside-in.json</pre><p>Add <code>--tls-ports 443</code> when 443 is in the selected port list. No nuclei, exploit template, write request or network sweep is used.</p><label for="probeImport">Import probe JSON</label><input type="file" id="probeImport" accept="application/json,.json"><p class="v2hint">The report records the probe machine and resolved target. Imported evidence does not authenticate that it ran outside your network.</p>`)+`</div>`)+
page('integrity','Integrity monitoring and canaries','Record approved file or response baselines, opt into scheduled checks, and create synthetic canaries in selected folders.',
 `<div class="v2buttons">${button('monitorRefresh','Refresh monitors')}</div><div id="monitorList"></div><div class="v2grid">`+
 card('7. Create an integrity baseline',field('monitorName','Monitor name')+select('monitorKind','Baseline type',[['files','Files, model store, manifests and prompts'],['behavior','Fixed model responses']])+`<div data-mk="files">${field('monitorPath','Absolute model store, file, or prompt folder')}</div><div data-mk="behavior">${field('monitorUrl','Model endpoint','http://127.0.0.1:11434')}${field('monitorModel','Model identity')}${select('monitorProvider','Provider',[['ollama','Ollama'],['openai','OpenAI-compatible']])}${field('monitorKeyEnv','Credential environment variable, optional')}<label for="monitorPrompts">Fixed prompts, one per line, up to five</label><textarea id="monitorPrompts">Reply with exactly the word READY.&#10;What is 2 plus 2? Answer with one digit.</textarea>${check('monitorAuthorized','I authorize these recurring inference probes when this monitor is enabled')}</div>${field('monitorInterval','Check interval in seconds','3600','number')}${button('monitorCreate','Record baseline')}<p class="v2hint">New schedules start disabled. Enable a monitor below after recording its baseline. Checks run only while this app is running. Large stores have a 120-second hashing budget; use smaller scoped baselines if incomplete. Response drift is a signal, not proof of a swapped model.</p>`)+
 card('6. Plant a local canary',field('canaryName','Canary label')+field('canaryFolder','Folder for a new fake .env file')+button('canaryCreate','Create synthetic canary')+`<p class="v2hint">Creates a new .env.canary-* file without modifying existing files. Contains a fake key and loopback callback URL. Routed disclosure or a callback hit appears in Violations. The gateway must be running to receive callbacks. A hit can come from an owner or scanner; it is not proof of exfiltration. External Thinkst callbacks are not provisioned by this local tool.</p><div id="canaryList"></div>`)+`</div>`));

let assetData={assets:[],policies:[]},protectionData={},violationData={},editingPolicy='default';
const value=id=>$(id).value.trim();const lines=id=>value(id).split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
async function safe(task){error('');try{return await task()}catch(e){error(e.message)}}
async function readApi(path){const r=await fetch('/api/'+path);const data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed');return data}
function options(id,rows,label,empty='Select an asset'){const prior=$(id).value;$(id).innerHTML=`<option value="">${empty}</option>`+rows.map(x=>`<option value="${esc(x.id)}">${esc(label(x))}</option>`).join('');if(rows.some(x=>x.id===prior))$(id).value=prior;}
async function refreshAssets(){assetData=await readApi('assets');$('assetSummary').textContent=assetData.assets.length+' registered assets · Risk is a transparent prioritization index, not a safety score. '+assetData.scope;
 $('assetList').innerHTML=assetData.assets.length?assetData.assets.map(a=>`<details class="finding"><summary><span class="pill">${esc(a.kind)}</span><b>${esc(a.name)}</b><span class="v2stat">${a.risk.score}</span><span>${esc(a.risk.label)} priority · ${a.risk.evidenceCoveragePercent}% control evidence coverage</span></summary><div class="evidence"><p class="path">${esc(a.target)}</p><p>Policy: ${esc(a.policyId)} · Owner: ${esc(a.owner||'unassigned')} · ${esc(a.source)}</p><table><tr><th>Control</th><th>Result</th><th>Evidence</th></tr>${a.checks.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.status)}</td><td>${esc(c.evidence)}</td></tr>`).join('')}</table><p class="v2hint">${esc(a.risk.rubric)}</p><p>Control deficit ${a.risk.components.controlDeficit} + finding contribution ${a.risk.components.findingContribution}</p>${a.toolPins?'<p>'+Object.keys(a.toolPins).length+' MCP descriptor hashes saved.</p>':''}</div></details>`).join(''):'<div class="empty">No assets registered. Discover a selected project folder or model endpoint to begin.</div>';
 for(const id of ['assignAsset','routeAsset'])options(id,assetData.assets,a=>a.name+' · '+a.kind);
 options('mcpAsset',assetData.assets.filter(a=>a.kind==='mcp'),a=>a.name,'Optional matching asset');
 for(const id of ['assignPolicy','previewPolicy','editPolicy'])options(id,assetData.policies,p=>p.name,'Select a policy');
 if(!value('editPolicy'))$('editPolicy').value='default';if(!value('assignPolicy'))$('assignPolicy').value='default';if(!value('previewPolicy'))$('previewPolicy').value='default';loadPolicy(value('editPolicy'));}
function loadPolicy(id){const p=assetData.policies.find(p=>p.id===id);if(!p)return;editingPolicy=id;$('policyName').value=p.name;$('policyMode').value=p.mode;for(const n of ['security','privacy','safety'])$('policy'+n[0].toUpperCase()+n.slice(1)).checked=p[n];for(const [id,key] of [['policyInput','maxInputChars'],['policyOutput','maxOutputChars'],['policyTokens','maxOutputTokens'],['policyRate','requestsPerMinute'],['policyBudget','maxSessionActions'],['policySystem','systemInstruction']])$(id).value=p[key];for(const [id,key] of [['policyTools','allowedTools'],['policyDomains','allowedDomains'],['policyPhrases','blockedPhrases']])$(id).value=p[key].join('\n');}
async function refreshProtection(){protectionData=await readApi('protection');$('gatewayStatus').textContent=(protectionData.gateway.running?'Gateway listening':'Gateway stopped')+' · '+protectionData.gateway.url+' · Direct traffic bypasses enforcement.';$('routeList').innerHTML=protectionData.routes.map(r=>`<p><b>${esc(assetData.assets.find(a=>a.id===r.assetId)?.name||r.assetId)}</b> · ${r.enabled?'Enabled':'Disabled'} <button class="quiet" data-toggle-route="${esc(r.id)}" data-enabled="${!r.enabled}">${r.enabled?'Disable':'Enable'}</button></p>`).join('');document.querySelectorAll('[data-toggle-route]').forEach(b=>b.onclick=()=>safe(async()=>{await api('routes/toggle',{routeId:b.dataset.toggleRoute,enabled:b.dataset.enabled==='true'});await refreshProtection();await refreshAssets()}));}
async function refreshViolations(){violationData=await readApi('violations');$('violationCounts').textContent=Object.entries(violationData.counts).map(([k,v])=>k+': '+v).join(' · ')||'No runtime decisions recorded.';renderViolations()}
function renderViolations(){const rows=(violationData.events||[]).filter(e=>value('violationFilter')==='all'||e.decision===value('violationFilter'));$('violationList').innerHTML=rows.length?`<table><tr><th>Time</th><th>Asset</th><th>Point</th><th>Decision</th><th>Rules</th></tr>${rows.map(e=>`<tr><td>${esc(new Date(e.createdAt).toLocaleString())}</td><td>${esc(assetData.assets.find(a=>a.id===e.assetId)?.name||e.assetId)}</td><td>${esc(e.point)}</td><td>${esc(e.decision)}</td><td>${esc(e.rules.join(', ')||'No rule matched')}</td></tr>`).join('')}</table><p class="v2hint">Latest 1,000 decisions shown. ${esc(violationData.retention)}</p>`:'<div class="empty">No decisions match this view.</div>'}
async function refreshMonitors(){const data=await readApi('monitors');$('monitorList').innerHTML=data.monitors.map(m=>`<details class="finding"><summary><b>${esc(m.name)}</b><span>${m.enabled?'Scheduled':'Paused'} · ${esc(m.lastResult.status)}</span></summary><div class="evidence"><p>${esc(m.path||m.url)} · ${m.baselineEntries} baseline entries · every ${m.intervalSeconds}s</p><pre>${esc(JSON.stringify(m.lastResult,null,2))}</pre><div class="v2buttons"><button class="secondary" data-monitor-check="${esc(m.id)}">Check now</button><button class="secondary" data-monitor-toggle="${esc(m.id)}" data-enabled="${!m.enabled}">${m.enabled?'Pause':'Enable schedule'}</button></div></div></details>`).join('')||'<div class="empty">No integrity baselines recorded.</div>';$('canaryList').innerHTML=data.canaries.map(c=>`<p><b>${esc(c.name)}</b><br><span class="path">${esc(c.path)}</span><br><span class="v2hint">${esc(c.url)}</span></p>`).join('');document.querySelectorAll('[data-monitor-check]').forEach(b=>b.onclick=()=>safe(async()=>{b.disabled=true;b.textContent='Checking…';await api('monitors/check',{id:b.dataset.monitorCheck});await refreshMonitors()}));document.querySelectorAll('[data-monitor-toggle]').forEach(b=>b.onclick=()=>safe(async()=>{await api('monitors/toggle',{id:b.dataset.monitorToggle,enabled:b.dataset.enabled==='true'});await refreshMonitors()}));}
document.querySelectorAll('[data-v2page]').forEach(b=>b.onclick=()=>safe(async()=>{show(b.dataset.v2page);if(b.dataset.v2page==='assets')await refreshAssets();if(b.dataset.v2page==='protection'){await refreshAssets();await refreshProtection()}if(b.dataset.v2page==='violations')await refreshViolations();if(b.dataset.v2page==='integrity')await refreshMonitors()}));
$('v2Refresh').onclick=()=>safe(refreshAssets);
$('assetExport').onclick=()=>download(JSON.stringify(assetData,null,2),'ai-assets.json','application/json');
$('saveAsset').onclick=()=>safe(async()=>{await api('assets/save',{kind:value('assetKind'),name:value('assetName'),target:value('assetTarget'),model:value('assetModel'),owner:value('assetOwner')});await refreshAssets()});
$('discoverAssets').onclick=()=>safe(async()=>{const r=await api('assets/discover',{roots:lines('discoveryRoots')});$('discoveryResult').textContent=r.assets.length+' assets found. '+r.coverage.gaps.join(' ');await refreshAssets()});
$('discoverModels2').onclick=()=>safe(async()=>{await api('assets/models',{kind:value('assetProvider'),url:value('assetEndpoint'),key:$('assetKey').value,authorized:$('assetAuthorized').checked});await refreshAssets()});
$('assignControls').onclick=()=>safe(async()=>{await api('assets/policy',{assetId:value('assignAsset'),policyId:value('assignPolicy'),owner:value('assignOwner')});await refreshAssets()});
$('attachEvidence').onclick=()=>safe(async()=>{if(!current)throw new Error('Run an assessment first.');await api('assets/report',{assetId:value('assignAsset'),report:current});await refreshAssets()});
$('mcpAsset').onchange=()=>{const a=assetData.assets.find(a=>a.id===value('mcpAsset'));if(a)$('mcpUrl').value=a.target};
$('mcpRun').onclick=()=>run('mcp',{url:value('mcpUrl'),key:$('mcpKey').value,assetId:value('mcpAsset'),authorized:$('mcpAuthorized').checked});
$('rtDiscover').onclick=()=>safe(async()=>{const r=await api('discover',{kind:value('rtProvider'),url:value('rtUrl'),key:$('rtKey').value,authorized:$('rtAuthorized').checked});$('rtModel').innerHTML=r.models.map(m=>`<option value="${esc(m.name)}">${esc(m.name)}</option>`).join('')});
$('rtRun').onclick=()=>run('redteam',{kind:value('rtProvider'),url:value('rtUrl'),key:$('rtKey').value,authorized:$('rtAuthorized').checked,model:value('rtModel'),maxCases:Number(value('rtCases')),budgetSeconds:Number(value('rtMinutes')||10)*60,seed:Number(value('rtSeed')||0),adaptive:$('rtAdaptive').checked});
$('editPolicy').onchange=()=>loadPolicy(value('editPolicy'));
$('policyNew').onclick=()=>{loadPolicy('default');editingPolicy=null;$('policyName').value='New policy'};
$('policySave').onclick=()=>safe(async()=>{const p={id:editingPolicy,name:value('policyName'),mode:value('policyMode'),security:$('policySecurity').checked,privacy:$('policyPrivacy').checked,safety:$('policySafety').checked,maxInputChars:Number(value('policyInput')),maxOutputChars:Number(value('policyOutput')),maxOutputTokens:Number(value('policyTokens')),requestsPerMinute:Number(value('policyRate')),maxSessionActions:Number(value('policyBudget')),allowedTools:lines('policyTools'),allowedDomains:lines('policyDomains'),blockedPhrases:lines('policyPhrases'),systemInstruction:value('policySystem')};const r=await api('policies/save',p);await refreshAssets();$('editPolicy').value=r.id;loadPolicy(r.id)});
$('previewRun').onclick=()=>safe(async()=>{$('previewResult').textContent=JSON.stringify(await api('policies/preview',{policyId:value('previewPolicy'),point:value('previewPoint'),content:$('previewText').value,...(value('previewTool')?{tool:value('previewTool')}:{})}),null,2)});
$('gatewayStart').onclick=()=>safe(async()=>{await api('gateway/start',{});await refreshProtection();await refreshAssets()});
$('gatewayStop').onclick=()=>safe(async()=>{await api('gateway/stop',{});await refreshProtection();await refreshAssets()});
$('routeSave').onclick=()=>safe(async()=>{const data={assetId:value('routeAsset'),provider:value('routeProvider'),keyEnv:value('routeKeyEnv'),authorized:$('routeAuthorized').checked};if(value('routeUpstream'))data.upstream=value('routeUpstream');const r=await api('routes/save',data);$('routeSecret').textContent='Client URL: '+r.clientUrl+'\nBearer token: '+r.token+'\n'+r.message;await refreshProtection();await refreshAssets()});
$('routeAsset').onchange=()=>{const a=assetData.assets.find(a=>a.id===value('routeAsset'));if(a){$('routeUpstream').value=a.kind==='agent'?'':a.target;if(Array.from($('routeProvider').options).some(o=>o.value===a.transport))$('routeProvider').value=a.transport}};
$('violationsRefresh').onclick=()=>safe(refreshViolations);$('violationFilter').onchange=renderViolations;$('violationsExport').onclick=()=>download(JSON.stringify(violationData,null,2),'runtime-decisions.json','application/json');
function deployControls(){const mode=value('deployMode');document.querySelectorAll('[data-dm]').forEach(e=>e.classList.toggle('hidden',!e.dataset.dm.split(',').includes(mode)));$('deployHint').textContent=({inference:'Read-only GET/HEAD checks. Model management authorization remains unknown when it cannot be established without modifying requests.',configuration:'Checks selected files and optional WebUI admin counts. Stored settings may differ from the effective deployment.',gpu:'Reads NVIDIA version, device permission and isolation evidence. Two named toolkit CVEs have explicit applicability caveats.',rag:'Read-only collection inventory and selected knowledge-source text checks. No vector writes. PDF extraction requires pypdf; visual concealment has limited coverage.',at_rest:'Redacted secret/PII patterns in text, logs and read-only SQLite samples. Values are never included in reports.',egress:'Active, bounded TCP/DNS probes through docker exec in the selected container. No metadata content requested.',signature:'Uses an installed model_signing CLI with the expected identity and issuer. Missing dependencies remain unknown.'})[mode]}
$('deployMode').onchange=deployControls;deployControls();
$('deployRun').onclick=()=>{const mode=value('deployMode');const c={mode};if(['inference','rag','egress'].includes(mode)){c.url=value('deployUrl');c.authorized=$('deployAuthorized').checked}if(['configuration','rag','at_rest','signature'].includes(mode))c.path=value('deployPath');if(mode==='at_rest')c.gitleaks=$('useGitleaks').checked;if(mode==='inference')c.service=value('deployService');if(mode==='rag')c.service=value('vectorService');if(mode==='configuration'){c.databasePath=value('deployDb');c.resources=$('deployResources').checked}if(mode==='gpu')c.multiTenant=$('gpuTenants').checked;if(mode==='egress'){c.container=value('egressContainer');c.dns=value('egressDns')}if(mode==='signature'){c.signature=value('signaturePath');c.identity=value('signerIdentity');c.issuer=value('signerIssuer');c.online=$('signatureOnline').checked}run('deployment',c)};
$('probeImport').onchange=()=>safe(async()=>{const f=$('probeImport').files[0];if(!f)return;if(f.size>2000000)throw new Error('Probe report exceeds 2 MB.');const r=JSON.parse((await f.text()).replace(/^\uFEFF/,''));if(r.schema!=='sha-outside-in-v1'||!Array.isArray(r.findings)||r.findings.length>100||!Array.isArray(r.limitations)||!r.createdAt||typeof r.target!=='string'||r.findings.some(x=>typeof x.name!=='string'||typeof x.evidence!=='string'||!Object.hasOwn(labels,x.status)))throw new Error('Invalid outside-in report.');r.limitations.unshift('Imported user-supplied evidence; probe location and contents have not been authenticated.');addReport(r);show('reports');$('probeImport').value=''});
$('monitorKind').onchange=()=>document.querySelectorAll('[data-mk]').forEach(e=>e.classList.toggle('hidden',e.dataset.mk!==value('monitorKind')));$('monitorKind').onchange();
$('monitorCreate').onclick=()=>safe(async()=>{$('monitorCreate').disabled=true;$('monitorCreate').textContent='Recording baseline…';try{const kind=value('monitorKind');await api('monitors/create',{kind,name:value('monitorName'),intervalSeconds:Number(value('monitorInterval')||3600),...(kind==='files'?{path:value('monitorPath')}:{url:value('monitorUrl'),model:value('monitorModel'),provider:value('monitorProvider'),prompts:lines('monitorPrompts'),keyEnv:value('monitorKeyEnv'),authorized:$('monitorAuthorized').checked})});await refreshMonitors()}finally{$('monitorCreate').disabled=false;$('monitorCreate').textContent='Record baseline'}});
$('monitorRefresh').onclick=()=>safe(refreshMonitors);$('canaryCreate').onclick=()=>safe(async()=>{await api('canaries/create',{name:value('canaryName'),path:value('canaryFolder')});await refreshMonitors()});
safe(async()=>{await refreshAssets();await refreshProtection()});


