  function tick(){if(deadline&&Date.now()>=deadline){clearValues();return;}el('pwStatus').textContent=deadline?`Clears in ${Math.ceil((deadline-Date.now())/1000)} seconds.`:'Clears when you leave this section or switch tabs.';}tick();if(deadline)timer=setInterval(tick,1000);
