el('pwPreset').onchange=()=>{const preset=el('pwPreset').value;if(preset==='custom')return;el('pwLength').value=({balanced:24,maximum:64,compatible:32,hex:64})[preset];Object.keys(GROUPS).forEach(g=>el('pw_'+g).checked=preset==='hex'?['lower','digits'].includes(g):preset==='compatible'?g!=='symbols':true);el('pwAmbiguous').checked=false;el('pwRequired').checked=preset!=='hex';el('pwExclude').value=preset==='hex'?'ghijklmnopqrstuvwxyz':'';};
el('passwords').querySelectorAll('select,input').forEach(x=>{if(x.id==='pwValues')return;x.addEventListener('change',()=>{if(hasValues)clearValues('Rules changed. Generate new values.');estimate();});x.addEventListener('input',()=>{if(hasValues)clearValues('Rules changed. Generate new values.');estimate();});});
new MutationObserver(()=>{if(el('passwords').classList.contains('hidden')&&hasValues)clearValues();}).observe(el('passwords'),{attributes:true,attributeFilter:['class']});
