(() => {
const pane=document.createElement('section');pane.id='scanCenter';pane.className='page hidden';
pane.innerHTML=`<div class="eyebrow">Local assessments / Paperclip and disks</div><h1>Paperclip & drive scans</h1><p class="intro">Find the actual workspaces configured in Paperclip, then scan selected agents and fixed drives in one queue. Results are saved locally between page refreshes.</p>
<div class="card setup"><h2>Find scan targets</h2><div class="row"><div class="field"><label for="scPort">Local Paperclip port</label><input id="scPort" type="number" min="1" max="65535" value="3100"></div><div class="field"><label for="scDistro">WSL distribution containing Paperclip agents</label><input id="scDistro" value="Ubuntu" spellcheck="false"></div><button class="secondary" id="scDiscover">Find agents and drives</button></div><p class="small muted">Discovery reads the local Paperclip inventory. Linux project paths are mapped through the selected WSL distribution. It does not start or change an agent.</p><p id="scNotice" role="status" class="small muted">Find targets to see the folders and drives before scanning.</p></div>
<div id="scSelection" class="hidden"><div class="two" style="margin-top:20px"><div class="card"><div class="sectionline" style="margin-top:0"><h2>Paperclip agents</h2><button class="quiet" id="scAllAgents">Select all agents</button></div><div id="scAgents" style="max-height:420px;overflow-y:auto;padding-right:10px"></div></div><div class="card"><div class="sectionline" style="margin-top:0"><h2>Fixed drives</h2><button class="quiet" id="scAllDrives">Select all drives</button></div><div id="scDrives"></div><p id="scAntivirus" class="small muted"></p><p class="small muted">A drive scan checks files for malware. It does not replace the agent assessment or scan inside every mounted WSL/VM virtual disk.</p></div></div>
<div class="card setup" style="margin-top:20px"><div class="row"><div class="field"><label for="scAgentMode">Agent inspection</label><select id="scAgentMode"><option value="deep">Deep scan · offline skills, code and dependencies</option><option value="standard">Focused skills and instructions</option></select></div><div class="field"><label for="scDriveHours">Maximum waiting time per drive</label><select id="scDriveHours"><option value="1">1 hour</option><option value="4" selected>4 hours</option><option value="12">12 hours</option></select></div></div><label class="check"><input type="checkbox" id="scAuthorized"><span>I own or am authorized to assess the selected agent folders and drives.</span></label><div class="actions"><button class="primary" id="scRun">Scan selected</button><button class="secondary" id="scRunAll">Scan all agents and drives</button></div><p class="small muted">Sequential scans; no agent execution, public dependency lookup or automatic remediation requested. Existing antivirus protection remains active independently. Cancellation stops waiting and skips remaining targets; a Defender service scan may continue.</p></div></div>
<div class="sectionline"><h2>Live queue</h2><span id="scQueueStatus" class="pill">IDLE</span></div><div id="scQueue" class="card">No batch started.</div><div class="sectionline"><h2>Saved batch reports</h2><button class="quiet" id="scRefresh">Refresh results</button></div><div id="scHistory" class="card">No saved batches loaded.</div>`;
document.querySelector('main').insertBefore(pane,document.querySelector('main > footer'));
const nav=document.createElement('button');nav.dataset.page='scanCenter';nav.textContent='▤ Paperclip & drive scans';nav.onclick=()=>{show('scanCenter');refresh()};document.querySelector('nav [data-page="overview"]').after(nav);
const shortcut=document.createElement('button');shortcut.className='secondary';shortcut.textContent='Find agents in Paperclip';shortcut.onclick=nav.onclick;document.querySelector('#agentscanner .setup').appendChild(shortcut);
const driveShortcut=document.createElement('button');driveShortcut.className='secondary';driveShortcut.textContent='Scan all fixed drives';driveShortcut.onclick=nav.onclick;document.querySelector('#modelscanner').appendChild(driveShortcut);
let catalog=null,working=false,refreshing=false;
const selected=()=>Array.from(pane.querySelectorAll('input[data-scan-target]:checked')).map(x=>x.value);
function choose(kind){pane.querySelectorAll('input[data-kind="'+kind+'"]').forEach(x=>{if(!x.disabled)x.checked=true})}
function targetHTML(r){return `<label class="check"><input type="checkbox" data-scan-target data-kind="${esc(r.kind)}" value="${esc(r.id)}" ${r.available?'':'disabled'}><span><b>${esc(r.name)}</b>${r.company?' · '+esc(r.company):''}${r.adapter?'<br><span class="small">Adapter: '+esc(r.adapter)+'</span>':''}<br><span class="path">${esc(r.path||r.sourcePath||'No configured workspace')}</span>${r.reason?'<br><span class="small">'+esc(r.reason)+'</span>':''}</span></label>`}
function busy(){for(const id of ['scDiscover','scRun','scRunAll'])$(id).disabled=working||running;}
const previousBusy=setBusy;setBusy=function(value){previousBusy(value);busy()};
$('scDiscover').onclick=async()=>{working=true;busy();error('');try{catalog=await api('scan-center/discover',{port:Number($('scPort').value),distribution:$('scDistro').value.trim()});$('scAgents').innerHTML=catalog.agents.map(targetHTML).join('')||'<p>No matching Hermes agents were returned.</p>';$('scDrives').innerHTML=catalog.drives.map(targetHTML).join('')||'<p>No fixed Windows drives are available to this app process.</p>';$('scNotice').textContent=catalog.agents.length+' matching agent(s), '+catalog.drives.length+' fixed drive(s). '+catalog.warnings.join(' ')+' '+catalog.limits;const av=catalog.antivirus;$('scAntivirus').textContent='Defender: '+(av.available?'installed':'unavailable')+' · '+av.mode+' · '+(av.elevated?'elevated app process':'standard app process; the scanner may require administrator rights')+'. Signatures: '+(av.signatureUpdated||'unknown');$('scSelection').classList.remove('hidden')}catch(e){error(e.message==='Not found'?'This section requires the installed backend update to be activated. Restart approval is still pending.':e.message)}finally{working=false;busy()}};
$('scAllAgents').onclick=()=>choose('agent');$('scAllDrives').onclick=()=>choose('drive');
async function begin(all){if(!catalog)return error('Find targets first.');if(all){choose('agent');choose('drive')}if(!$('scAuthorized').checked)return error('Confirm authorization for these selected folders and drives.');const targets=selected();if(!targets.length)return error('Select at least one available target.');await run('scan_batch',{discoveryId:catalog.discoveryId,targets,authorized:true,agentMode:$('scAgentMode').value,driveHours:Number($('scDriveHours').value)});await refresh();}
$('scRun').onclick=()=>begin(false);$('scRunAll').onclick=()=>begin(true);
function rowsHTML(rows){return '<div style="overflow-x:auto"><table><thead><tr><th>Target</th><th>Status</th><th>Findings / engine</th></tr></thead><tbody>'+rows.map(r=>`<tr><td><b>${esc(r.name)}</b><br><span class="path">${esc(r.path)}</span></td><td>${esc(r.status)}${r.status==='running'&&r.startedAt?'<br>'+Math.max(0,Math.floor((Date.now()-Date.parse(r.startedAt))/60000))+' min elapsed':''}</td><td>${esc(r.findingCount??'—')}${r.exitCode!==undefined?'<br>Exit '+esc(r.exitCode):''}${r.hresults?.length?'<br>'+esc(r.hresults.join(', ')):''}${r.error?'<br>'+esc(r.error):''}</td></tr>`).join('')+'</tbody></table></div>'}
async function refresh(){if(refreshing)return;refreshing=true;try{const response=await fetch('/api/scan-center');if(!response.ok)return;const s=await response.json();$('scQueueStatus').textContent=(s.current?.status||'idle').toUpperCase();if(s.current)$('scQueue').innerHTML=rowsHTML(s.current.rows);$('scHistory').innerHTML=s.history.length?s.history.map(r=>`<div class="row" style="margin:10px 0"><span class="field">${esc(new Date(r.createdAt).toLocaleString())} · ${esc(r.status)} · ${esc(r.coverage.finished)}/${esc(r.coverage.planned)} targets finished</span><button class="secondary" data-batch-report="${esc(r.id)}">Open report</button></div>`).join(''):'No saved batch reports yet.';$('scHistory').querySelectorAll('[data-batch-report]').forEach(b=>b.onclick=async()=>{try{const r=await api('scan-center/report',{id:b.dataset.batchReport});addReport(r);show('reports')}catch(e){error(e.message)}})}catch(e){$('scQueueStatus').textContent='UNAVAILABLE'}finally{refreshing=false}}
$('scRefresh').onclick=refresh;
const previousRender=render;render=function(){previousRender();if(current?.batchAssessment){const box=document.createElement('div');box.className='card';box.style.marginTop='20px';box.innerHTML='<h2>Per-target results</h2>'+rowsHTML(current.batchAssessment.targets);$('report').prepend(box)}};
setInterval(()=>{if(!pane.classList.contains('hidden')||running)refresh()},3000);
})();
/* RAYI_SCAN_CENTER_END */
